def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) > 0 and opp.get('budget', 0) > 0:
                    dangerous_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_danger = max(dangerous_prev) if dangerous_prev else highest_prev

    tight_supply = supply <= 17
    medium_supply = supply <= 20
    critical = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if critical:
        bid = max(0.92 * DAILY_SALARY, highest_danger + 3.0)
    elif tight_supply:
        bid = max(0.78 * DAILY_SALARY, highest_danger + 2.0)
    elif medium_supply:
        if highest_danger >= 90:
            bid = 0.52 * DAILY_SALARY
        else:
            bid = max(0.58 * DAILY_SALARY, highest_danger + 1.5)
    else:
        if pressured:
            bid = max(0.48 * DAILY_SALARY, min(highest_danger + 1.0, 0.72 * DAILY_SALARY))
        else:
            bid = 0.34 * DAILY_SALARY

    if day >= 8:
        if critical:
            bid = max(bid, 0.95 * DAILY_SALARY)
        elif pressured:
            bid = max(bid, 0.72 * DAILY_SALARY)

    reserve = 0.0
    if day <= 7:
        reserve = max(0.0, (10 - day) * 8.0)
    max_affordable = max(0.0, budget - reserve)
    if max_affordable <= 0:
        max_affordable = budget

    bid = min(bid, max_affordable, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            continue

    # If no one else is alive, bid to ensure full allocation for us cheaply
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Use only yesterday's immediate trace bids
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            yesterday_bids.append(float(b))
        except Exception:
            continue

    # Heuristic: typical winning bids around ~110 from survivalists; avoid going too high
    # Determine pressure
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units might be needed today given supply and fixed WATER_REQ
    # We don't know exact allocation rule, but we can use supply to decide aggressiveness.
    # Use int() to ensure indices safety.
    # target_units is how many WATER_REQ blocks supply suggests.
    target_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 1
    # Cap target_units to reasonable range
    if target_units < 1:
        target_units = 1
    if target_units > 3:
        target_units = 3

    # Base bid band
    # If opponents were bidding very high yesterday, conserve; else bid around their survival band.
    if highest_prev_bid >= DAILY_SALARY * 1.55:  # ~140
        base = avg_prev_bid if avg_prev_bid > 0 else (DAILY_SALARY * 0.6)
        # Conserve more if our hp is ok
        if my_hp > 4:
            base *= 0.75
        else:
            base *= 0.9
    else:
        # Aim slightly above their average to secure water, but not max
        base = avg_prev_bid if avg_prev_bid > 0 else (DAILY_SALARY * 0.6)
        # Push toward ~110-120 band
        # If base too low, lift it; if too high, moderate.
        if base < 95.0:
            base = 110.0
        elif base > 125.0:
            base = 120.0

    # Adjust for our hp: lower hp -> bid more
    if my_hp <= 2.0:
        base *= 1.25
    elif my_hp <= 4.0:
        base *= 1.12
    elif my_hp >= 8.0:
        base *= 0.9

    # Adjust for supply: higher supply -> bid slightly less
    # supply in [15,25]
    supply_factor = 1.0
    if supply >= 22.0:
        supply_factor = 0.92
    elif supply <= 17.0:
        supply_factor = 1.08
    base *= supply_factor

    # Translate target_units into a mild scaling (more units available -> less need for extreme bids)
    if target_units == 1:
        base *= 1.08
    elif target_units == 3:
        base *= 0.95

    # Final cap by budget and ensure nonnegative
    bid = float(base)
    if bid < 0.0:
        bid = 0.0

    # Don't exceed budget; also avoid bidding above what salary could justify too aggressively
    max_reasonable = my_budget
    if max_reasonable < 0.0:
        max_reasonable = 0.0

    # Keep bid within a practical ceiling to avoid waste
    practical_ceiling = min(max_reasonable, DAILY_SALARY * 1.6)
    if bid > practical_ceiling:
        bid = practical_ceiling

    # If budget is extremely low, bid remaining (still capped)
    if my_budget <= 1.0:
        bid = my_budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    highest_prev = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev = max(highest_prev, prev['bid'])
    base_bid = max(DAILY_SALARY * 0.5, highest_prev + 1.0)
    if my_status['no_water_days'] > 0 or my_status['hp'] <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    return min(my_status['budget'], base_bid)
